/*
  Home only (`landing-page.tsx`): the lead, the workbench (`hero-source-card.tsx`), the two
  editorial beats under it, and the closed walkthrough disclosure (`hero-film-disclosure.tsx`).
  Shared chrome and global sheets are not touched; every `:global` hook below re-inks existing
  statement, action or scene markup, and only inside `.home`.

  Warm paper and near-black ink; cobalt is for actions only, amber only marks evidence. No
  radius anywhere: rules and one raised sheet separate things, not nested rounded cards.
*/

.home {
  --home-paper: #f6f3ec;
  --home-stone: #ece7dc;
  --home-sheet: #fffdf8;
  --home-ink: #14171a;
  --home-muted: #4b5057;
  --home-cobalt: #2347b8;
  --home-cobalt-deep: #1b3891;
  --home-amber: #f2b73a;
  --home-amber-wash: #fff1c7;
  --home-amber-ink: #8a5a00;
  --home-rule: rgb(20 23 26 / 0.16);
  --home-rule-strong: rgb(20 23 26 / 0.32);
  --home-mono: ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
  --home-ease: cubic-bezier(0.23, 1, 0.32, 1);
}

/*
  Home only: the shared 64px header is transparent with light text and sits over this paper
  until it scrolls. While it is unscrolled -- menu open or not -- re-ink only the header row:
  the wordmark (its mark and its `b`, which the shared sheet colours itself), the desktop
  section links and the direct action links. The menu summary and its dark panel are not
  matched, and `data-scrolled="1"` keeps the shared dark header. No shared variable is changed.
*/
.home > header:not([data-scrolled="1"]) > :global(.wordmark),
.home > header:not([data-scrolled="1"]) > :global(.wordmark) :is(b, svg),
.home > header:not([data-scrolled="1"]) > :global(.one-path-primary-nav) > :global(.site-nav-direct),
.home > header:not([data-scrolled="1"]) > :global(.nav-actions) > a {
  color: var(--home-ink);
}

/* The ring paints on the paper around the row's controls; panel links keep the shared ring. */
.home > header:not([data-scrolled="1"]) > :global(.wordmark):focus-visible,
.home > header:not([data-scrolled="1"]) > :global(.one-path-primary-nav) > :global(.site-nav-direct):focus-visible,
.home > header:not([data-scrolled="1"]) > :global(.nav-actions) > a:focus-visible,
.home > header:not([data-scrolled="1"]) > details > summary:focus-visible {
  outline: 2px solid var(--home-cobalt);
  outline-offset: 2px;
}

/* ------------------------------------------------------------------------ 01 lead and workbench */

/* `section.` outranks the shared scene ground and `.lv2-hero` padding on the same element. */
section.hero {
  background: var(--home-paper);
  color: var(--home-ink);
  /* The 64px header overlays the top of this section: reserve it plus a little air. */
  padding-block: calc(4rem + clamp(1rem, 2.5vw, 2rem)) clamp(2.5rem, 6vw, 4.5rem);
}

/* Wider than the shared measure: the workbench is the page's one expansive surface. */
section.hero .layout {
  display: grid;
  gap: clamp(1.5rem, 3vw, 2.5rem);
  width: min(1320px, calc(100% - 2 * var(--lv2-gutter)));
}

/*
  The statement's three parts become this grid's items (`display: contents` on its wrapper), so
  the headline can sit left of the support and actions on a wide screen and above them on a phone
  without the shared component changing.
*/
.intro {
  display: grid;
  gap: 0.75rem 3rem;
  align-items: end;
  min-width: 0;
}

.intro :global(.lv2-hero-text) {
  display: contents;
}

.intro :global(.lv2-hero-text) > * {
  text-align: start;
}

.intro :global(.lv2-eyebrow) {
  margin: 0;
  color: var(--home-muted);
}

.intro :global(.lv2-hero-h1) {
  margin: 0;
  max-width: none;
  color: var(--home-ink);
  font-size: clamp(2rem, 1.2rem + 3.2vw, 3.75rem);
  font-weight: 600;
  line-height: 1.02;
  letter-spacing: -0.035em;
}

.intro :global(.lv2-hero-support) {
  margin: 0;
  max-width: 34rem;
  color: var(--home-muted);
  font-size: 1.0625rem;
  line-height: 1.5;
}

@media (min-width: 960px) {
  .intro {
    grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
    grid-template-areas:
      "eyebrow eyebrow"
      "title support"
      "title actions";
  }

  .intro :global(.lv2-eyebrow) { grid-area: eyebrow; }
  .intro :global(.lv2-hero-h1) { grid-area: title; }
  .intro :global(.lv2-hero-support) { grid-area: support; }
  .actionsBlock { grid-area: actions; }
}

.actionsBlock {
  display: grid;
  gap: 0.25rem;
  min-width: 0;
}

.actionsBlock :global(.lv2-actions) {
  justify-content: flex-start;
  gap: 0.5rem 1.5rem;
  margin: 0;
}

/* One filled action, in cobalt; it answers a press without delaying it. */
section.hero .actionsBlock :global(.btn.lv2-cta) {
  min-height: 48px;
  border-color: var(--home-cobalt);
  background: var(--home-cobalt);
  color: #fff;
  box-shadow: none;
  transition: transform 160ms var(--home-ease), background-color 160ms ease;
}

section.hero .actionsBlock :global(.btn.lv2-cta):active {
  transform: scale(0.97);
}

@media (hover: hover) and (pointer: fine) {
  section.hero .actionsBlock :global(.btn.lv2-cta):hover {
    background: var(--home-cobalt-deep);
  }
}

/* The commercial action stays a real link, quieter in ink rather than a second button. */
section.hero .actionsBlock :global(.lv2-text-link) {
  min-height: 44px;
  color: var(--home-ink);
  font-size: 1rem;
  text-decoration-color: var(--home-rule-strong);
}

section.hero .actionsBlock :global(.lv2-actions a:focus-visible) {
  outline: 2px solid var(--home-cobalt);
  outline-offset: 3px;
}

.intakeNote {
  margin: 0;
  color: var(--home-muted);
  font-size: 1rem;
  line-height: 1.5;
}

/* The accepted formats, under the workbench rather than in the first screen's stack. */
section.hero .intake {
  margin: 0;
  color: var(--home-muted);
  font-family: inherit;
  font-size: 1rem;
  line-height: 1.55;
  text-align: start;
}

/* The workbench: one top rule, numbered steps, no nested panels. */
.bench {
  counter-reset: home-step;
  min-width: 0;
  border-top: 2px solid var(--home-ink);
  color: var(--home-ink);
  text-align: start;
}

.benchHead {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.25rem 1.5rem;
  padding-block: 0.75rem;
  border-bottom: 1px solid var(--home-rule);
}

.benchTitle {
  margin: 0;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: 0;
}

/* The shared `h1, h2, h3` rule sets light `--text-hi` on the h2 itself, so it never inherits `.bench` ink. */
.bench .benchTitle {
  color: var(--home-ink);
}

/* A hollow mark: prepared, not run. Never a tick and never a score. */
.runStatus {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0;
  color: var(--home-muted);
  font: 500 0.8125rem/1.4 var(--home-mono);
}

.runStatus::before {
  content: "";
  flex: none;
  width: 0.5rem;
  height: 0.5rem;
  border: 1.5px solid currentColor;
  border-radius: 50%;
}

.benchGrid {
  display: grid;
  gap: 1.25rem;
  padding-top: 1.25rem;
}

/* Step numbers are counters, so the page's figure guard never sees a typed digit. */
.step::before {
  counter-increment: home-step;
  content: counter(home-step, decimal-leading-zero) "\2002" attr(data-step);
  display: block;
  margin-bottom: 0.5rem;
  color: var(--home-muted);
  font: 600 0.75rem/1.4 var(--home-mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

@media (min-width: 960px) {
  .benchGrid {
    grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
    grid-template-areas:
      "locator passage"
      "page passage"
      "page regions";
    grid-template-rows: auto auto 1fr;
    column-gap: 0;
    row-gap: 1rem;
  }

  .locator { grid-area: locator; }
  .passagePane { grid-area: passage; }
  .pageFrame { grid-area: page; }
  .regionPane { grid-area: regions; align-self: end; }

  .locator,
  .pageFrame {
    padding-right: clamp(1.5rem, 3vw, 3rem);
  }

  .passagePane,
  .regionPane {
    padding-left: clamp(1.5rem, 3vw, 3rem);
    border-left: 1px solid var(--home-rule);
  }
}

.locator,
.passagePane,
.pageFrame,
.regionPane {
  min-width: 0;
}

.filename {
  margin: 0;
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.35;
  overflow-wrap: anywhere;
}

.locatorMeta {
  margin: 0.25rem 0 0;
  color: var(--home-muted);
  font-size: 1rem;
  line-height: 1.5;
}

.metaField {
  font: 600 0.75rem/1 var(--home-mono);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.sourceLinks {
  display: flex;
  flex-wrap: wrap;
  gap: 0 1.25rem;
  margin: 0.25rem 0 0;
}

.home a.quietLink,
.home a.evidenceLink,
.home a.diffLink {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  min-height: 44px;
  color: var(--home-cobalt);
  /* Explicit: otherwise these inherit the shared 15px body size. */
  font-size: 1rem;
  font-weight: 600;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 0.2em;
}

.home a.quietLink {
  font-weight: 500;
}

.home a.quietLink:focus-visible,
.home a.evidenceLink:focus-visible,
.home a.diffLink:focus-visible {
  outline: 2px solid var(--home-cobalt);
  outline-offset: 2px;
}

/*
  The page, as large as the column allows, windowed from just above the highest selectable region
  to just under the lowest (the component sets the aspect ratio and the sheet's offset); the full
  page is one link below it.
*/
.pageWindow {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--home-rule);
  background: #fff;
}

.pageWindow::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 2.5rem;
  background: linear-gradient(to bottom, rgb(255 255 255 / 0), #fff);
  pointer-events: none;
}

.pageSheet {
  position: relative;
}

.pageSheet img {
  display: block;
  width: 100%;
  height: auto;
}

.box {
  position: absolute;
  outline: 1.5px dashed var(--home-amber-ink);
  outline-offset: 1px;
}

.box[data-selected="1"] {
  outline: 2px solid var(--home-ink);
  background: rgb(242 183 58 / 0.3);
}

.boxMark {
  position: absolute;
  top: -1px;
  right: calc(100% + 4px);
  display: grid;
  place-items: center;
  min-width: 1.125rem;
  height: 1.125rem;
  padding-inline: 0.2rem;
  background: var(--home-amber-ink);
  color: #fff;
  font: 700 0.6875rem/1 var(--home-mono);
}

.box[data-selected="1"] .boxMark {
  background: var(--home-ink);
}

.pageAbsent {
  margin: 0;
  padding: 2rem 1.25rem;
  border: 1px dashed var(--home-rule-strong);
  color: var(--home-muted);
}

.paneLabel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.375rem 0.75rem;
  margin: 0 0 0.75rem;
  font-size: 1rem;
  font-weight: 600;
}

/* A label of what the text is, in ink -- deliberately not a coloured badge. */
.extracted {
  padding: 0.125rem 0.5rem;
  border: 1px solid var(--home-ink);
  font: 600 0.75rem/1.5 var(--home-mono);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.quote {
  margin: 0;
  padding: 1rem 1.125rem;
  border-left: 3px solid var(--home-amber);
  background: var(--home-sheet);
  font-size: 1.125rem;
  font-variant-numeric: tabular-nums;
  line-height: 1.6;
  overflow-wrap: break-word;
}

.citation {
  margin: 0.625rem 0 0;
  color: var(--home-muted);
  font: 0.8125rem/1.5 var(--home-mono);
  overflow-wrap: anywhere;
}

.contextNote {
  max-width: 46ch;
  margin: 1rem 0 0;
  padding-top: 0.75rem;
  border-top: 1px solid var(--home-rule);
  font-size: 1rem;
  line-height: 1.55;
}

.home a.evidenceLink {
  margin-top: 0.25rem;
}

.regionsLabel {
  margin: 0 0 0.5rem;
  color: var(--home-muted);
  font: 600 0.75rem/1.4 var(--home-mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.regionList {
  display: grid;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

/* Native buttons; the pressed one carries the amber mark. Selection itself is instant. */
.regionButton {
  display: grid;
  grid-template-columns: 1.75rem minmax(0, 1fr);
  align-items: center;
  gap: 0.75rem;
  width: 100%;
  min-height: 3rem;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--home-rule-strong);
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: start;
  cursor: pointer;
  transition: transform 120ms var(--home-ease);
}

.regionButton[aria-pressed="true"] {
  border-color: var(--home-ink);
  background: var(--home-amber-wash);
  box-shadow: inset 3px 0 0 var(--home-amber);
}

.regionButton:active {
  transform: scale(0.985);
}

.regionButton:focus-visible {
  outline: 2px solid var(--home-cobalt);
  outline-offset: 2px;
}

@media (hover: hover) and (pointer: fine) {
  .regionButton:hover {
    border-color: var(--home-ink);
  }
}

.regionLetter {
  display: grid;
  place-items: center;
  width: 1.75rem;
  height: 1.75rem;
  background: var(--home-amber-ink);
  color: #fff;
  font: 700 0.8125rem/1 var(--home-mono);
}

.regionButton[aria-pressed="true"] .regionLetter {
  background: var(--home-ink);
}

.regionText {
  display: grid;
  gap: 0.125rem;
  min-width: 0;
}

.regionRole {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.35;
}

.regionWhere {
  color: var(--home-muted);
  font: 0.8125rem/1.4 var(--home-mono);
  overflow-wrap: anywhere;
}

/* The record strip: what a reader can take away from this one passage. */
.record {
  margin-top: clamp(1.5rem, 3vw, 2.25rem);
  padding-top: 1rem;
  border-top: 1px solid var(--home-ink);
}

.recordList {
  display: grid;
  gap: 1rem 2rem;
  margin: 0;
}

@media (min-width: 640px) {
  .recordList {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1100px) {
  .recordList {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

.recordList dt {
  font-size: 1rem;
  font-weight: 600;
}

.recordList dd {
  margin: 0.25rem 0 0;
  color: var(--home-muted);
  font-size: 1rem;
  line-height: 1.5;
}

.digestShort {
  color: var(--home-ink);
  font: 0.8125rem/1.4 var(--home-mono);
}

.count {
  color: var(--home-ink);
  font-variant-numeric: tabular-nums;
}

.details {
  margin-top: 1rem;
  border-top: 1px solid var(--home-rule);
}

.detailsSummary {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  width: fit-content;
  min-height: 2.75rem;
  font-weight: 600;
  cursor: pointer;
  list-style: none;
}

.detailsSummary::-webkit-details-marker {
  display: none;
}

.detailsSummary::before {
  content: "";
  flex: none;
  border-block: 0.3125rem solid transparent;
  border-inline-start: 0.5rem solid var(--home-ink);
  transition: transform 150ms var(--home-ease);
}

.details[open] > .detailsSummary::before {
  transform: rotate(90deg);
}

.detailsSummary:focus-visible {
  outline: 2px solid var(--home-cobalt);
  outline-offset: 2px;
}

.detailList {
  display: grid;
  gap: 0.5rem;
  margin: 0.25rem 0 1rem;
  font-size: 1rem;
  line-height: 1.5;
}

.detailList > div {
  display: grid;
  grid-template-columns: 10rem minmax(0, 1fr);
  gap: 0.75rem;
}

.detailList dt {
  color: var(--home-muted);
}

.detailList dd {
  margin: 0;
  overflow-wrap: anywhere;
}

.digest {
  font: 0.8125rem/1.5 var(--home-mono);
  word-break: break-all;
}

.detailRegions {
  display: grid;
  gap: 0.75rem;
  margin: 0 0 1rem;
  padding: 0;
  list-style: none;
}

.detailRegions li {
  display: grid;
  grid-template-columns: 1.75rem minmax(0, 1fr);
  align-items: start;
  gap: 0.25rem 0.75rem;
  padding-top: 0.75rem;
  border-top: 1px solid var(--home-rule);
}

.detailRegions li > a {
  grid-column: 2;
  width: fit-content;
}

.detailRegionText {
  display: grid;
  gap: 0.125rem;
  min-width: 0;
  font-size: 1rem;
}

/* -------------------------------------------------------------- 02 why this case is difficult */

section.difficulty {
  background: var(--home-stone);
  color: var(--home-ink);
}

.split {
  display: grid;
  gap: clamp(1.5rem, 4vw, 3.5rem);
}

@media (min-width: 960px) {
  .split {
    grid-template-columns: minmax(0, 5fr) minmax(0, 7fr);
  }

  .reserved,
  .filmSlot {
    grid-column: 1 / -1;
  }
}

.splitHead,
.receiveHead {
  min-width: 0;
}

.splitHead :global(.lv2-h2) {
  font-size: clamp(1.75rem, 1.1rem + 2.2vw, 2.75rem);
  line-height: 1.08;
  letter-spacing: -0.03em;
}

.splitHead :global(.lv2-scene-support),
.receiveHead :global(.lv2-scene-support) {
  color: var(--home-muted);
  font-size: 1.0625rem;
  line-height: 1.55;
}

.diffList {
  counter-reset: home-diff;
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
}

.diffList > li {
  counter-increment: home-diff;
  display: grid;
  grid-template-columns: 3.5rem minmax(0, 1fr);
  column-gap: 1rem;
  padding-block: 1.25rem;
  border-top: 1px solid var(--home-rule-strong);
}

.diffList > li::before {
  content: counter(home-diff, decimal-leading-zero);
  grid-row: 1 / span 3;
  color: var(--home-amber-ink);
  font-size: 1.75rem;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.02em;
}

.diffList > li > * {
  grid-column: 2;
}

.diffList h3 {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.3;
}

.diffList p {
  max-width: 52ch;
  margin: 0.375rem 0 0;
  color: var(--home-muted);
  font-size: 1rem;
  line-height: 1.55;
}

.diffList b {
  color: var(--home-ink);
}

.diffList .diffLinks {
  display: flex;
  flex-wrap: wrap;
  gap: 0 1.25rem;
  margin-top: 0.125rem;
}

.reserved {
  max-width: 72ch;
  margin: 0;
  padding-top: 1rem;
  border-top: 1px dashed var(--home-rule-strong);
  color: var(--home-muted);
  font-size: 1rem;
  line-height: 1.55;
}

.filmSlot {
  min-width: 0;
}

/* ------------------------------------------------------------------- 03 what you receive */

section.receive {
  background: var(--home-paper);
  color: var(--home-ink);
}

.receiveHead {
  max-width: 52rem;
}

.receiveHead :global(.lv2-h2) {
  font-size: clamp(2rem, 1.2rem + 3vw, 3.5rem);
  line-height: 1.04;
  letter-spacing: -0.035em;
}

.receiveGrid {
  display: grid;
  align-items: start;
  gap: clamp(1.5rem, 4vw, 3.5rem);
  margin-top: clamp(1.75rem, 4vw, 3rem);
}

@media (min-width: 960px) {
  .receiveGrid {
    grid-template-columns: minmax(0, 7fr) minmax(0, 5fr);
  }
}

/* The one raised object on the page: a record, set like a sheet of paper. */
.recordSheet {
  min-width: 0;
  padding: clamp(1.25rem, 3vw, 2.25rem);
  border: 1px solid var(--home-rule);
  border-top: 3px solid var(--home-ink);
  background: var(--home-sheet);
  box-shadow: 0 24px 48px -32px rgb(20 23 26 / 0.35);
}

.recordKind {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.25rem 1rem;
  margin: 0 0 1rem;
  font: 600 0.8125rem/1.4 var(--home-mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.recordState {
  color: var(--home-muted);
}

.recordQuote {
  margin: 0;
  padding-left: 1rem;
  border-left: 3px solid var(--home-amber);
  font-size: clamp(1.25rem, 1rem + 1vw, 1.625rem);
  line-height: 1.4;
  letter-spacing: -0.01em;
}

.recordFields {
  display: grid;
  gap: 0.625rem;
  margin: 1.5rem 0 0;
  padding-top: 1rem;
  border-top: 1px solid var(--home-rule);
}

.recordFields > div {
  display: grid;
  grid-template-columns: 6.5rem minmax(0, 1fr);
  gap: 0.75rem;
}

.recordFields dt {
  color: var(--home-muted);
  font: 600 0.75rem/1.6 var(--home-mono);
  letter-spacing: 0.06em;
}

.recordFields dd {
  margin: 0;
  font-size: 1rem;
  line-height: 1.5;
  overflow-wrap: anywhere;
}

.recordFields code {
  font: 0.8125rem/1.5 var(--home-mono);
  word-break: break-all;
}

.recordLinks {
