/* ------------------------------------------------------------------------------- phones */

/*
  390px: the lead shrinks to a compact headline, one sentence and one action row, so the source
  name starts near the first screen's lower third even with the consent notice above the header.
  Measured at 390x844 with a fresh consent notice before the reorder: source name 538px, but the
  page frame 1195px, under the whole passage. The page now follows the name and its one-line
  location directly, half a gap below; its frame top and first ink are recorded by
  mobile-raster-recovery/diagnose-source-image.cjs, not assumed here.
*/
@media (max-width: 639.98px) {
  section.hero {
    padding-block: calc(4rem + 0.25rem) 2.5rem;
  }

  section.hero .layout {
    gap: 0.5rem;
  }

  .intro {
    gap: 0.25rem;
  }

  section.hero .intro :global(.lv2-eyebrow) {
    display: none;
  }

  .intro :global(.lv2-h1-line) {
    display: inline;
  }

  .intro :global(.lv2-hero-support) {
    font-size: 1rem;
    line-height: 1.5;
  }

  .actionsBlock :global(.lv2-actions) {
    gap: 0.25rem 1rem;
  }

  section.hero .actionsBlock :global(.btn.lv2-cta) {
    min-height: 44px;
    padding-inline: 1.125rem;
  }

  .benchHead {
    padding-block: 0.25rem;
  }

  /* The headline above already says what this is; the h2 stays for the article's accessible name. */
  .benchTitle {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* In the page's sans the status fits one line at 390px; in mono it wraps to two. */
  .runStatus {
    font-family: inherit;
  }

  .benchGrid {
    gap: 1rem;
    padding-top: 0.25rem;
  }

  .step::before {
    margin-bottom: 0.125rem;
  }

  /*
    The file name is the source step here, so its generated "01 Source" label is dropped; the
    element keeps the count so the passage and record steps stay 02 and 03.
  */
  .locator::before {
    display: none;
  }

  .locator {
    counter-increment: home-step;
  }

  .filename {
    font-size: 1rem;
  }

  .locatorMeta {
    margin-top: 0.125rem;
    font-size: 1rem;
    line-height: 1.4;
  }

  .locator + .pageFrame {
    margin-top: -0.5rem;
  }

  .quote {
    padding: 0.75rem 0.875rem;
    font-size: 1.0625rem;
  }

  .diffList > li {
    grid-template-columns: 2.5rem minmax(0, 1fr);
    column-gap: 0.75rem;
  }

  .diffList > li::before {
    font-size: 1.25rem;
  }
}

@media (max-width: 479.98px) {
  .detailList > div,
  .recordFields > div {
    grid-template-columns: minmax(0, 1fr);
    gap: 0.125rem;
  }
}

