}

.readerHead h2,
.readerFaq h2 {
  margin: 0;
  color: var(--home-ink);
  font-size: clamp(1.75rem, 1.2rem + 2vw, 2.75rem);
  line-height: 1.1;
  letter-spacing: -0.025em;
}

.readerGuide p {
  max-width: 60ch;
  margin: 0.625rem 0 0;
  color: var(--home-muted);
  font-size: 1rem;
  line-height: 1.6;
