.readerChecks {
  display: grid;
  gap: 1.25rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.readerChecks li {
  padding-block-start: 1rem;
  border-top: 1px solid var(--home-rule-strong);
}

.readerChecks h3 {
