/*
  The walkthrough film at the foot of scene 02 (`hero-film-disclosure.tsx`). It sits on the
  stone ground now, so the rules are ink-tinted and the marker is the evidence amber; the focus
  ring is the action cobalt like every other control on Home.
*/
.film {
  --film-rule: var(--home-rule-strong);
  --film-mark: var(--home-amber-ink);
  margin-block: clamp(1.5rem, 4vw, 2.5rem);
  border-block: 1px solid var(--film-rule);
  text-align: start;
}

.filmSummary {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  min-height: 2.75rem;
  padding-block: 0.75rem;
  cursor: pointer;
  font-weight: 600;
  line-height: 1.4;
  list-style: none;
}

.filmSummary::-webkit-details-marker {
  display: none;
}

.filmSummary::before {
  content: "";
  flex: none;
  border-block: 0.3125rem solid transparent;
  border-inline-start: 0.5rem solid var(--film-mark);
  transition: transform 150ms ease;
}

.film[open] > .filmSummary::before {
  transform: rotate(90deg);
}

.filmSummary:focus-visible {
  outline: 2px solid var(--home-cobalt);
  outline-offset: 3px;
}

.filmBody {
  padding-block-end: 1.25rem;
}

@media (prefers-reduced-motion: reduce) {
  .filmSummary::before {
    transition: none;
  }
}
